"""Training data generated by the real physics engine.

Every row comes from an actual MuJoCo throw: the body is placed on open ground, picks up a block,
optionally walks / jumps, and throws with the sampled force and direction; the engine's own flight
record supplies the targets. Nothing is computed analytically.

Each sample starts from the same prepared checkpoint, so samples are independent and the whole
dataset is reproducible from (config, seed, n). Datasets are stored as JSON with a manifest
(seed, config hash, sampling ranges, row count, SHA-256 of the rows).
"""
from __future__ import annotations

import hashlib
import json
import math
import random
import time
from pathlib import Path
from typing import Callable

import numpy as np

from ..config import config_hash
from ..world.physics import ActionError, PhysicsWorld
from . import MLError
from .features import ALL_COLUMNS, throw_row

# A cleared throwing range: the thrower stands near the west edge and throws east along the open strip
# y in [-3, 3] (platforms sit at |y| >= 3.5 west of x = 4.6; the terrace starts at x = 4.6, ~14 m away).
# Loose objects are removed from the strip so every flight is free flight onto open ground.
THROW_SITE = (-9.5, 0.0)
DEFAULT_RANGES = {
    "force": (20.0, 200.0),          # N (engine maximum is 200)
    "elevation_deg": (5.0, 88.0),    # above horizontal
    "azimuth_deg": (-12.0, 12.0),    # heading, 0 = east, along the cleared strip
    "jump_probability": 0.4,         # share of throws released at take-off from a jump
    "walk_probability": 0.25,        # share of throws released while walking
    "walk_speed": (0.5, 3.5),
    "walk_heading_deg": (-80.0, 80.0),
    "objects": ["block_01", "rock"],
    "object_weights": [0.8, 0.2],
}


class _Site:
    """A reusable throwing range: one world, one prepared checkpoint per object."""

    def __init__(self, cfg: dict):
        self.cfg = cfg
        self.world = PhysicsWorld(cfg)
        self.world._recording = True
        self.ready: dict[str, dict] = {}

    def prepare(self, oid: str) -> dict:
        if oid in self.ready:
            return self.ready[oid]
        w = PhysicsWorld(self.cfg)
        x, y = THROW_SITE
        for other in sorted(w.active):
            if w.specs[other].movable and other != oid:
                w.setup_remove(other)
        w.setup_agent(x, y)
        w.setup_place(oid, [x + 0.9, y, w.half_extent_z(oid) + 0.002])
        w.setup_finish()
        w.pick_up(oid)
        w.settle(max_time=1.0)
        st = w.get_state()
        self.ready[oid] = st
        return st

    def throw(self, oid: str, force: float, direction: list[float], mode: str, walk_speed: float = 0.0,
              walk_heading: float = 0.0) -> dict | None:
        """One throw from the prepared state. mode: stand | jump | walk."""
        w = self.world
        w.set_state(self.prepare(oid))
        w.events.clear()
        w.completed_flights.clear()
        w.flights.clear()
        try:
            if mode == "jump":
                w.jump(wait="takeoff")
            elif mode == "walk":
                h = math.radians(walk_heading)
                # accelerate for ~1 s at the chosen speed, then release while still moving
                w.target_vel[:] = [math.cos(h) * walk_speed, math.sin(h) * walk_speed]
                for _ in range(int(1.0 / w.dt)):
                    w._step()
            r = w.throw(oid, direction, force, wait="impact", max_wait=15.0)
        except ActionError:
            return None
        rec = None
        # finish the flight so first-impact data (range, flight time) is in the engine record
        for _ in range(int(10.0 / w.dt)):
            if oid not in w.flights:
                break
            w._step()
        for fr in w.completed_flights:
            if fr.get("flight_id") == r.get("flight_id"):
                rec = fr
        if rec is None and r.get("flight_time") is not None:
            rec = r
        row = throw_row(r, rec)
        if row is not None and rec is not None:
            # Only clean free flights count: the first thing hit must be the open ground.
            row["first_impact_with"] = list(rec.get("first_impact_with") or [])
        return row


def _direction(elev_deg: float, az_deg: float) -> list[float]:
    e, a = math.radians(elev_deg), math.radians(az_deg)
    return [math.cos(e) * math.cos(a), math.cos(e) * math.sin(a), math.sin(e)]


def generate_throw_dataset(cfg: dict, n: int, seed: int = 0, ranges: dict | None = None,
                           progress: Callable[[int, int], None] | None = None) -> dict:
    """Run `n` real throws in the engine and return {"manifest": ..., "rows": [...]}."""
    if not (1 <= n <= 200_000):
        raise MLError("invalid_argument", "n must be between 1 and 200000.")
    rg = {**DEFAULT_RANGES, **(ranges or {})}
    rnd = random.Random(seed)
    site = _Site(cfg)
    rows, failed, off_range, t0 = [], 0, 0, time.perf_counter()
    for i in range(n):
        oid = rnd.choices(rg["objects"], weights=rg["object_weights"])[0]
        force = rnd.uniform(*rg["force"])
        elev = rnd.uniform(*rg["elevation_deg"])
        az = rnd.uniform(*rg["azimuth_deg"])
        u = rnd.random()
        mode = "jump" if u < rg["jump_probability"] else (
            "walk" if u < rg["jump_probability"] + rg["walk_probability"] else "stand")
        row = site.throw(oid, force, _direction(elev, az), mode,
                         walk_speed=rnd.uniform(*rg["walk_speed"]), walk_heading=rnd.uniform(*rg["walk_heading_deg"]))
        if row is None or row.get("flight_time") is None:
            failed += 1
        elif row.get("first_impact_with") != ["ground"]:
            off_range += 1
        else:
            row["mode"] = mode
            row["object"] = oid
            row.pop("first_impact_with", None)
            rows.append(row)
        if progress and (i + 1) % 100 == 0:
            progress(i + 1, n)
    return {"manifest": _manifest(cfg, "engine_throws", rows, seed=seed, requested=n, failed=failed,
                                  hit_something_other_than_ground=off_range, ranges=rg,
                                  throw_site=list(THROW_SITE), seconds=round(time.perf_counter() - t0, 2)),
            "rows": rows}


def _manifest(cfg: dict, source: str, rows: list[dict], **extra) -> dict:
    blob = json.dumps(rows, sort_keys=True).encode()
    return {"source": source, "rows": len(rows), "columns": sorted(ALL_COLUMNS),
            "rows_sha256": hashlib.sha256(blob).hexdigest(), "physics_config_hash": config_hash(cfg),
            "created_at": time.time(), **extra}


def _behaviour_manifest(cfg: dict, source: str, kind: str, rows: list[dict], **extra) -> dict:
    """Manifest for an engine-generated behaviour dataset. Carries `kind` + the DatasetSpec vocabulary,
    so training routes through the same columns as a log-built dataset of that kind (vocab_from_manifest)."""
    from .datasets import columns_for
    ins, tgts = columns_for(kind)
    m = _manifest(cfg, source, rows, **extra)
    m["kind"] = kind
    m["inputs"] = sorted(ins)
    m["targets"] = sorted(tgts)
    return m


def _row(record: dict) -> dict:
    """Rounded row dict, matching the rounding build_dataset() applies to log rows."""
    return {k: (round(v, 6) if isinstance(v, float) else v) for k, v in record.items()}


def _prepared_state(cfg: dict, build) -> dict:
    """A settled engine checkpoint: the same recipe _Site.prepare uses, parameterised by the caller."""
    w = PhysicsWorld(cfg)
    build(w)
    w.setup_finish()
    w.settle(max_time=1.0)
    return w.get_state()


# --------------------------------------------------------------------------- engine jump dataset
JUMP_SPOT = (-2.5, -2.1)                       # open ground (same spot as the HVE jump tests)
# Every jump sample varies exactly what the jump row's inputs describe: what is carried (mass) and
# what it stands on at take-off (stacked blocks -> take-off feet height). The engine is deterministic,
# so this (mass x platform) grid is the full, honest sample space of the jump row's inputs.
# The ring is deliberately absent: it is the island's ritual object (the around-a-block rule) and
# destabilises prepared scenes; carried loads stay plain bodies (blocks 5 kg, rock 12 kg).
JUMP_CARRIED = ([None, "block_01", "rock"], [0.5, 0.3, 0.2])
JUMP_STACK_IDS = ("block_01", "block_04")      # distinct ids: blocks 0.25 m half-height each
JUMP_STACK_N = (0, 1, 2)                       # blocks under the feet: 0.0 m / 0.5 m / 1.0 m


def _place_stack(w, ids: tuple[str, ...], x: float, y: float, n: int) -> None:
    """Stack n distinct block ids at (x, y). setup_place() positions one id, so stacking needs
    a different id per level (all island blocks share the same half-height)."""
    if not ids or n <= 0:
        return
    hz = w.half_extent_z(ids[0])
    for k in range(min(n, len(ids))):
        w.setup_place(ids[k], [x, y, (2 * k + 1) * hz + 0.002])


def _jump_site(w, x: float, y: float, stack_ids: tuple[str, ...], stack_n: int,
               carried: str | None) -> None:
    for other in sorted(w.active):
        if w.specs[other].movable and other != stack_ids[0] and other != carried \
                and other not in stack_ids:
            w.setup_remove(other)
    _place_stack(w, stack_ids, x, y, stack_n)
    if stack_n:
        # Stage the platform's own settle BEFORE anything stands on it: spawning the agent and
        # placeables together shoves objects around (a settle collision once threw the ring 5 m).
        w.setup_finish()
        w.settle(max_time=0.8)
    w.setup_agent(x, y)
    w.setup_finish()
    w.settle(max_time=1.0)
    if carried:
        # Only now, everything already at rest: place the carried object beside the agent and
        # collect it. Spawning it before the stage settles let collisions fling it out of reach
        # or off the island ('object_lost').
        w.setup_place(carried, [x - w.hw - 0.4, y, w.half_extent_z(carried) + 0.002])
        w.setup_finish()
        w.settle(max_time=0.3)
        w.pick_up(carried)
        w.settle(max_time=0.2)


def generate_jump_dataset(cfg: dict, n: int, seed: int = 0,
                          progress: Callable[[int, int], None] | None = None) -> dict:
    """Run `n` real jumps in the engine, varying carried load and take-off platform, and return
    {"manifest": ..., "rows": [...]} in the log-built jump dataset's own row schema."""
    if not (1 <= n <= 200_000):
        raise MLError("invalid_argument", "n must be between 1 and 200000.")
    from .datasets import _jump_row
    rnd = random.Random(seed)
    w = PhysicsWorld(cfg)
    w._recording = True
    ready: dict[tuple, dict] = {}
    rows: list[dict] = []
    failed = 0
    t0 = time.perf_counter()
    for i in range(n):
        carried = rnd.choices(JUMP_CARRIED[0], weights=JUMP_CARRIED[1])[0]
        stack_n = int(rnd.choice(JUMP_STACK_N))
        key = (carried, stack_n)
        if key not in ready:
            try:
                ready[key] = _prepared_state(
                    cfg, lambda w2, s=JUMP_STACK_IDS, k=stack_n, c=carried: _jump_site(w2, *JUMP_SPOT, s, k, c))
            except ActionError:
                failed += 1            # this site variant refused to build; skip that sample
                continue
        w.set_state(ready[key])
        w.events.clear()
        try:
            r = w.jump(wait="landing")
        except ActionError:
            failed += 1
            continue
        row = _jump_row({}, r)
        if row is None:          # jump never left its support -> engine record without an apex
            failed += 1
            continue
        rows.append(_row(row))
        if progress and (i + 1) % 50 == 0:
            progress(i + 1, n)
    manifest = _behaviour_manifest(
        cfg, "engine_jumps", "jump", rows, seed=seed, requested=n, failed=failed,
        jump_spot=list(JUMP_SPOT), seconds=round(time.perf_counter() - t0, 2))
    return {"manifest": manifest, "rows": rows}


# --------------------------------------------------------------------------- engine climb dataset
CLIMB_SPOT = (-9.5, 2.0)                       # open ground west of the terrace
CLIMB_LEDGES = (("block_02",), ("block_02", "block_03"))   # 0.5 m ledge, 1.0 m stacked ledge
CLIMB_CARRIED = ([None, "block_06"], [0.6, 0.4])
CLIMB_OFFSET_RANGE = (0.05, 0.35)              # gap between agent and the ledge's west face, m
CLIMB_JITTER_DEG = 20.0                        # heading error: some rays miss the ledge entirely


def _climb_site(w, x: float, y: float, stack_ids: tuple[str, ...], ledge_dx: float,
                carried: str | None) -> None:
    for other in sorted(w.active):
        if w.specs[other].movable and other != stack_ids[0] and other != carried \
                and other not in stack_ids:
            w.setup_remove(other)
    _place_stack(w, stack_ids, x + 2 * w.hw + ledge_dx, y, len(stack_ids))
    w.setup_finish()
    w.settle(max_time=0.8)          # the ledge settles before the agent spawns near it
    w.setup_agent(x, y)
    w.setup_finish()
    w.settle(max_time=1.0)
    if carried:
        # Behind the agent (west), away from the climb direction, so it neither blocks the
        # ledge ray nor changes the climb geometry; placed only once everything is at rest.
        w.setup_place(carried, [x - w.hw - 0.4, y, w.half_extent_z(carried) + 0.002])
        w.setup_finish()
        w.settle(max_time=0.3)
        w.pick_up(carried)
        w.settle(max_time=0.2)


def generate_climb_dataset(cfg: dict, n: int, seed: int = 0,
                           progress: Callable[[int, int], None] | None = None) -> dict:
    """Run `n` real climbs in the engine against prepared block ledges (single and stacked), varying
    ledge height, standing gap, heading jitter and carried load, and return rows in the log-built
    climb dataset's own schema (success / height_gained targets)."""
    if not (1 <= n <= 200_000):
        raise MLError("invalid_argument", "n must be between 1 and 200000.")
    from .datasets import _climb_row
    rnd = random.Random(seed)
    w = PhysicsWorld(cfg)
    w._recording = True
    ready: dict[tuple, dict] = {}
    rows: list[dict] = []
    failed = 0
    t0 = time.perf_counter()
    for i in range(n):
        stack_ids = CLIMB_LEDGES[int(rnd.randrange(len(CLIMB_LEDGES)))]
        carried = rnd.choices(CLIMB_CARRIED[0], weights=CLIMB_CARRIED[1])[0]
        ledge_dx = round(rnd.uniform(*CLIMB_OFFSET_RANGE), 2)
        jitter = math.radians(rnd.uniform(-CLIMB_JITTER_DEG, CLIMB_JITTER_DEG))
        d = np.array([math.cos(jitter), math.sin(jitter)])
        key = (stack_ids, carried, ledge_dx)
        if key not in ready:
            try:
                ready[key] = _prepared_state(
                    cfg, lambda w2, s=tuple(stack_ids), c=carried, dx=ledge_dx: _climb_site(w2, *CLIMB_SPOT, s, dx, c))
            except ActionError:
                failed += 1            # this site variant refused to build; skip that sample
                continue
        w.set_state(ready[key])
        w.events.clear()
        try:
            r = w.climb(d)
        except ActionError:
            failed += 1            # ray missed the ledge (gap/jitter) or the mount was refused
            continue
        # The action-record layer stamps a completed climb's result with success=1 before it lands in
        # the log; the raw engine dict doesn't carry it. Give the row builder the same view.
        r.setdefault("success", 1)
        row = _climb_row({}, r)
        if row is None:
            failed += 1
            continue
        rows.append(_row(row))
        if progress and (i + 1) % 50 == 0:
            progress(i + 1, n)
    manifest = _behaviour_manifest(
        cfg, "engine_climbs", "climb", rows, seed=seed, requested=n, failed=failed,
        climb_spot=list(CLIMB_SPOT), seconds=round(time.perf_counter() - t0, 2))
    return {"manifest": manifest, "rows": rows}


def dataset_from_session_events(db, session_ids: list[int]) -> dict:
    """Rows from throws that actually happened in recorded sessions (pairs throw_release + flight_end)."""
    rows = []
    for sid in session_ids:
        evs = db.events(sid, types=["throw_release", "flight_end"])
        releases = {e["data"]["flight_id"]: e["data"] for e in evs if e["type"] == "throw_release"}
        for e in evs:
            if e["type"] == "flight_end" and e["data"].get("kind") == "throw":
                rel = releases.get(e["data"].get("flight_id"))
                if rel:
                    row = throw_row(rel, e["data"])
                    if row is not None and row.get("flight_time") is not None:
                        row["session_id"] = sid
                        rows.append(row)
    return {"manifest": {"source": "recorded_sessions", "session_ids": session_ids, "rows": len(rows),
                         "rows_sha256": hashlib.sha256(json.dumps(rows, sort_keys=True).encode()).hexdigest(),
                         "created_at": time.time()},
            "rows": rows}


def save_dataset(ds: dict, path: str | Path) -> Path:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(ds), encoding="utf-8")
    return p


def load_dataset(path: str | Path) -> dict:
    p = Path(path)
    if not p.exists():
        raise MLError("unknown_dataset", f"No dataset at {p}.")
    ds = json.loads(p.read_text(encoding="utf-8"))
    blob = json.dumps(ds["rows"], sort_keys=True).encode()
    if ds["manifest"].get("rows_sha256") and hashlib.sha256(blob).hexdigest() != ds["manifest"]["rows_sha256"]:
        raise MLError("dataset_tampered", f"Dataset {p.name} does not match its manifest hash.")
    return ds


def dataset_from_session_events(events: list[dict], cfg: dict) -> dict:
    """Build a dataset from raw throw_release/flight_end events.

    This is a simplified version of recorded_throw_dataset for use by agent tools,
    where events are already extracted from the database.

    Args:
        events: List of event dicts with 'type' and 'data' keys.
        cfg: Configuration dict (for physics config hash).

    Returns:
        Dataset dict with 'manifest' and 'rows' keys.
    """
    from .features import throw_row
    from ..config import config_hash

    releases = {e["data"]["flight_id"]: e["data"] for e in events if e["type"] == "throw_release"}
    rows = []
    for e in events:
        if e["type"] == "flight_end" and e["data"].get("kind") == "throw":
            rel = releases.get(e["data"].get("flight_id"))
            if rel:
                row = throw_row(rel, e["data"])
                if row is not None and row.get("flight_time") is not None:
                    rows.append(row)

    return {
        "manifest": {
            "source": "session_events",
            "rows": len(rows),
            "rows_sha256": hashlib.sha256(json.dumps(rows, sort_keys=True).encode()).hexdigest(),
            "physics_config_hash": config_hash(cfg),
            "created_at": time.time(),
        },
        "rows": rows,
    }
